window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[41]={"id":"041","numero":41,"titre":"Endométriose","objectifs":[{"id":"41-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","contenu":"<div class=\"notion-course\"><p>Trois entités distinctes mais fréquemment associées chez la femme en âge de procréer. L’<span>endométriose</span> n’est pas <em>systématiquement</em> pathologique : c’est sa traduction symptomatique (douleur, <span class=\"nc-red nc-bold\">infertilité</span>) qui en fait une <strong>maladie</strong>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Définition</th><th>Forme « maladie »</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Dysménorrhée</strong></td>\n            <td><span>Règles douloureuses</span> — <span class=\"nc-yellow_bg nc-bold\">douleurs</span> <span class=\"nc-yellow_bg nc-bold\">pelviennes</span> contemporaines des menstruations</td>\n            <td>\n              <strong>Primaire / essentielle</strong> : <span>6-24 mois</span> après les 1ʳᵉˢ règles, idiopathique, sensible aux <span>antalgiques</span> usuels<br>\n              <strong>Secondaire / organique</strong> : tardive, s’aggrave au fil des cycles, EVA &gt; 7/10, résistante aux antalgiques (<span class=\"nc-red nc-bold\">endométriose</span>, adénomyose, sténose cervicale…)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endométriose</strong></td>\n            <td><strong>Définition histologique</strong> : <span class=\"nc-yellow_bg\">présence de </span><span><span class=\"nc-yellow_bg\">tissu de type endométrial</span></span><span class=\"nc-yellow_bg\"> en dehors de la cavité utérine</span></td>\n            <td><strong>Endométriose maladie</strong> = lorsqu’elle provoque <span><span class=\"nc-red nc-bold\">douleurs</span></span> et/ou <span><span class=\"nc-red nc-bold\">infertilité</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Adénomyose</span></strong></td>\n            <td>\n              <span><span class=\"nc-yellow_bg\">Infiltration</span></span><span class=\"nc-yellow_bg\"> </span><em><span class=\"nc-yellow_bg\">diffuse ou focale</span></em><span class=\"nc-yellow_bg\"> du </span><span><span class=\"nc-yellow_bg\">myomètre</span></span><span class=\"nc-yellow_bg\"> par des cellules endométriales</span><br>\n              → formation de <strong><span>microkystes endométriaux intra-myométriaux</span></strong>\n            </td>\n            <td>\n              <strong>Diffuse interne</strong> : foyers dans tout le myomètre<br>\n              <strong>Focale externe</strong> : agrégats circonscrits dans des zones précises\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Catégories anatomiques des lésions d’endométriose</h4>\n\n      <table>\n        <thead>\n          <tr><th>Forme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Péritonéale superficielle</span></strong></td>\n            <td>\n              Lésions de petite taille, limitées au péritoine<br>\n              Aspects : <span class=\"nc-blue_bg\">rouges/florides/hémorragiques</span> ; <span class=\"nc-blue_bg\">taches brunâtres</span> ; <span class=\"nc-blue_bg\">microkystes noirs</span> ; <span class=\"nc-blue_bg\">lésions étoilées blanches</span> ; <span class=\"nc-blue_bg\">défauts péritonéaux</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Endométriome</span></span></strong></td>\n            <td>\n              <span>Lésion</span> kystique ovarienne (<em><span class=\"nc-yellow_bg\">kyste endométriosique de l’ovaire</span></em>)<br>\n              Origine : invagination à point de départ à la surface de l’ovaire<br>\n              Contenu : <span><span class=\"nc-blue_bg\">liquide visqueux marron chocolat</span></span> (cellules détruites + sang dégradé)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Endométriose</span> pelvienne <span class=\"nc-red nc-bold\">profonde</span></span></strong><br><em>(sous-péritonéale)</em></td>\n            <td>\n              Nodules infiltrant à <span>&gt; 5 mm</span> sous le péritoine, à <strong>composante fibromusculaire</strong> &gt; endométriale<br>\n              Compartiment antérieur : <strong>vessie, uretères</strong><br>\n              Compartiment postérieur : <strong>ligaments utéro-sacrés, vagin, paroi antérieure <span class=\"nc-purple nc-bold\">rectum</span>/sigmoïde</strong><br>\n              Autres : <span class=\"nc-purple nc-bold\">racines sacrées</span>, paroi abdominale, côlon droit, appendice, iléon terminal\n            </td>\n          </tr>\n          <tr>\n            <td><strong>À distance</strong></td>\n            <td>Rares localisations : endométriose <strong><span class=\"nc-purple nc-bold\">pulmonaire</span></strong>, <strong><span class=\"nc-purple nc-bold\">cérébrale</span></strong>, <span class=\"nc-purple nc-bold\">diaphragmatique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les 3 catégories peuvent être <em>isolées ou associées</em>. L’<span>évolution</span> est <span>imprévisible</span> : certaines patientes restent toute leur vie avec des lésions superficielles, d’autres voient toutes les formes s’associer et s’aggraver en <span>&lt; 10 ans</span> de règles.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 40 — Algies pelviennes</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/adenomyosis","label":"Radiopaedia : Adenomyosis"}]},{"id":"41-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","contenu":"<div class=\"notion-course\"><p>Maladie <span>multifactorielle</span> (facteurs génétiques + environnementaux) dont la <strong><span>prévalence</span> apparente augmente</strong> ces dernières décennies. Sa fréquence réelle reste difficile à chiffrer (forme asymptomatique fréquente, absence de test diagnostique simple).</p>\n\n      <h4><span class=\"nc-red nc-bold\">Endométriose</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Indicateur</th><th>Valeurs / population</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Du diagnostic possible <em><span class=\"nc-pink_bg\">dès la</span> <span class=\"nc-pink_bg\">puberté</span></em> <span class=\"nc-red nc-bold\">jusqu’à la </span><span><span class=\"nc-red nc-bold\">ménopause</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Prévalence</span> générale</strong></td>\n            <td><span>6-15 %</span> des femmes en âge de procréer (toutes formes confondues)</td>\n          </tr>\n          <tr>\n            <td><strong>Femmes consultant pour <span class=\"nc-yellow_bg nc-bold\">infertilité</span></strong></td>\n            <td><span>15-20 %</span> (jusqu’à <span>50 %</span> selon séries)</td>\n          </tr>\n          <tr>\n            <td><strong>Femmes avec <span class=\"nc-yellow_bg nc-bold\">douleurs</span> <span class=\"nc-yellow_bg nc-bold\">pelviennes</span></strong></td>\n            <td><span>25-33 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Retard diagnostique</strong></td>\n            <td><span><span class=\"nc-pink nc-bold\">7-10 ans</span></span> selon les études</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Facteurs de risque</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>FR de <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire menstruel</strong></td>\n            <td>\n              <strong><span class=\"nc-blue_bg\">Ménarche précoce</span></strong> ; <strong><span class=\"nc-blue_bg\">nulliparité</span></strong><br>\n              <strong><span class=\"nc-blue_bg\">Cycles courts</span></strong> ; <span class=\"nc-blue_bg\">hyperménorrhée</span> ; <span class=\"nc-blue_bg\">ménorragie</span><br>\n              Anomalie müllérienne (malformation utérine) ; <span class=\"nc-pink_bg\">geste endo-utérin</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Génétique</span></strong></td>\n            <td><span><span class=\"nc-blue_bg\">Risque</span> × 5</span> chez les apparentées au 1ᵉʳ degré (variants en cours d’identification)</td>\n          </tr>\n          <tr>\n            <td><strong>Néo-nataux</strong></td>\n            <td><span class=\"nc-red nc-bold\">Petit poids de naissance</span> ; <span class=\"nc-red nc-bold\">ATCD de saignement vaginal en période néo-natale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              ATCD d’abus ou violence sexuelle<br>\n              <span class=\"nc-red_bg\">Faible IMC</span><br>\n              <span class=\"nc-brown_bg\">Perturbateurs endocriniens</span> (rôle plausible non démontré)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Adénomyose</h4>\n\n      <ul>\n        <li><span>Incidence</span> augmente après <span>35 ans</span></li>\n        <li>Pourrait concerner près de <span>50 %</span> des femmes</li>\n        <li>Souvent associée à l’<span class=\"nc-red nc-bold\">endométriose</span></li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"41-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l’endométriose","contenu":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> de l’endométriose reste partiellement élucidée. La théorie dominante associe un <strong><span><span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire de sang menstruel</span></strong> à une <strong>capacité d’élimination péritonéale diminuée</strong> et à des anomalies hormonales/inflammatoires locales favorisant l’implantation et la <span class=\"nc-red nc-bold\">persistance</span> des lésions.</p>\n\n      <h4>Caractéristique histologique principale</h4>\n\n      <ul>\n        <li>Composante de <span>tissu endométrial</span> entouré d’un <strong><span>stroma</span></strong></li>\n        <li>Comportement cyclique mimant celui de l’endomètre :\n          <ol>\n            <li><span class=\"nc-blue_bg\">Croissance cyclique</span> → <span class=\"nc-blue_bg\">desquamation</span> → hémorragie pendant les règles</li>\n            <li>Sang et cellules desquamées <strong>non éliminés</strong> → <span><span class=\"nc-red nc-bold\">réaction inflammatoire cyclique locale</span></span></li>\n          </ol>\n        </li>\n      </ul>\n\n      <h4>Provenance des lésions — arguments pour le <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire</h4>\n\n      <ul>\n        <li>FR de <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire ↗ le risque d’endométriose</li>\n        <li><span class=\"nc-blue_bg\">Prédominance des lésions dans le </span><strong><span class=\"nc-blue_bg\">compartiment postérieur du pelvis et à gauche</span></strong></li>\n        <li>Implants disséminés sur le trajet de circulation du liquide péritonéal (analogie avec les métastases du cancer de l’ovaire)</li>\n        <li><strong>Péritoine des femmes atteintes</strong> aurait une capacité diminuée d’élimination du sang et des cellules (le <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire survient chez la majorité des femmes, mais toutes ne développent pas une endométriose)</li>\n      </ul>\n\n      <h4>Mécanismes de <span class=\"nc-red nc-bold\">croissance</span> et de <span class=\"nc-red nc-bold\">persistance</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies hormonales</strong></td>\n            <td>\n              <strong><span>Surexpression du récepteur aux œstrogènes</span></strong><br>\n              <strong><span>Résistance à la progestérone</span></strong><br>\n              <strong><span>Surexpression de l’aromatase</span></strong><br>\n              → favorise <span class=\"nc-red nc-bold\">croissance</span> + <span class=\"nc-red nc-bold\">persistance</span> des lésions\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réaction <span>inflammatoire</span></strong></td>\n            <td>\n              Production locale d’<span>IL-6</span>, de <span>TNF</span>, stress oxydatif<br>\n              → endométriose = <em>maladie <span>inflammatoire</span> locale</em> avec réponse immunitaire péritonéale\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Invasion / néoangiogenèse</strong></td>\n            <td>\n              <span class=\"nc-pink_bg\">Surexpression des </span><strong><span><span class=\"nc-pink_bg\">métalloprotéinases</span></span></strong><br>\n              <span class=\"nc-pink_bg\">Surexpression du </span><span><span class=\"nc-pink_bg\">VEGF</span></span><br>\n              → potentiel d’invasion et de néoangiogenèse marqué\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes des douleurs</h4>\n\n      <ul>\n        <li><span class=\"nc-brown_bg\">Nociception</span> · <span class=\"nc-brown_bg\">hyperalgie</span> · <strong><span><span class=\"nc-brown_bg\">sensibilisation centrale</span></span></strong></li>\n        <li><strong>Corrélation</strong> entre <em>typologie</em> des douleurs et <em>localisation</em> des lésions</li>\n        <li><span>Pas de lien</span> entre <em>intensité des symptômes</em> et <em>étendue/profondeur</em> de l’endométriose</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <span class=\"nc-red nc-bold\">endométriose</span> <em>peu étendue</em> peut être <strong>très symptomatique</strong>, et inversement une atteinte <span class=\"nc-red nc-bold\">profonde</span> peut être <em>pauci-symptomatique</em>. Le bilan d’extension n’est <strong>jamais</strong> proportionné à la sévérité clinique.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"41-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une endométriose","contenu":"<div class=\"notion-course\"><p>Le <span>diagnostic d’<span class=\"nc-red nc-bold\">endométriose</span></span> est avant tout <strong>clinique</strong>. Les examens d’imagerie évaluent la <em>gravité et la cartographie</em> de la maladie ; leur normalité <strong>n’exclut pas</strong> le diagnostic (en particulier en cas d’<span class=\"nc-red nc-bold\">endométriose</span> superficielle).</p>\n\n      <h4>Circonstances diagnostiques</h4>\n\n      <ul>\n        <li>Diagnostic fortuit chez les femmes pauci/asymptomatiques (imagerie, <span>chirurgie</span> incidente)</li>\n        <li>Symptômes plus marqués chez les femmes avec <strong>règles mensuelles + activité ovarienne non freinée</strong> par contraception hormonale :\n          <ul>\n            <li><span class=\"nc-pink_bg\">Adolescentes</span></li>\n            <li>Femmes jeunes nullipares à l’arrêt de la contraception pour <span>grossesse</span></li>\n            <li>Femmes multipares avec contraception <strong>mécanique</strong> (DIU cuivre, stérilisation tubaire…)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Triade symptomatique</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-yellow_bg\">Symptômes douloureux de survenue cyclique</span></strong><span class=\"nc-yellow_bg\"> rythmée par les règles</span> ⭐</li>\n        <li><strong><span class=\"nc-yellow_bg\">Manifestations spécifiques d’organe</span></strong> (digestives, urinaires, scapulaires…)</li>\n        <li><span>Infertilité</span></li>\n      </ul>\n\n      <h4><span class=\"nc-blue_bg\">Symptômes douloureux</span> gynécologiques</h4>\n\n      <table>\n        <thead>\n          <tr><th>Symptôme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Dysménorrhée</strong><br><em>(1ᵉʳ symptôme dans la majorité des cas)</em></td>\n            <td>\n              <strong>Type</strong> : <span class=\"nc-blue_bg\">douleurs sourdes</span><br>\n              <strong>Topographie</strong> : abdomino-pelvienne (<span class=\"nc-red nc-bold\">hypogastre</span>, <span class=\"nc-red nc-bold\">fosses iliaques</span>, <span class=\"nc-red nc-bold\">flancs</span>, <span class=\"nc-red nc-bold\">bas du dos</span>)<br>\n              <strong>Délai</strong> : souvent dès les 1ʳᵉˢ règles<br>\n              <strong>Horaire</strong> : <span>cyclique</span>, survenant juste avant les règles<br>\n              <strong>Durée</strong> : <span><span class=\"nc-pink nc-bold\">1-2 jours</span></span>, parfois plus (crescendo)<br>\n              <strong>Associé</strong> : <span class=\"nc-blue_bg\">ménorragies</span> souvent associées<br>\n              <strong>Calmants</strong> : <span>AINS</span> ✅ ; pilule en mode cyclique ✅<br>\n              <em>Conséquence</em> : <span class=\"nc-red nc-bold\">absentéisme</span> scolaire ou professionnel\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dyspareunie <span class=\"nc-red nc-bold\">profonde</span></strong></td>\n            <td>\n              Déclenchée par les <strong><span class=\"nc-red nc-bold\">pénétrations profondes</span></strong>, généralement dans le <span class=\"nc-red nc-bold\">cul-de-sac postérieur</span><br>\n              Causes possibles : <span class=\"nc-orange_bg\">adénomyose</span> ; <span class=\"nc-orange_bg\">endométriose superficielle du cul-de-sac recto-utérin</span> ; <strong><span class=\"nc-orange_bg\">endométriose profonde</span></strong> (rétrocervicale, ligaments utéro-sacrés, culs-de-sac vaginaux) → <em>justifie une <span>IRM</span></em><br>\n              <em>Conséquence</em> : retentissement sexuel + diminue les chances de conception spontanée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Méno-/métrorragies douloureuses</strong></td>\n            <td>Évocateur d’<span>adénomyose</span> (toujours douloureuses dans ce contexte)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg nc-bold\">Douleurs</span> intermenstruelles</strong></td>\n            <td>\n              <span class=\"nc-yellow_bg nc-bold\">Pelviennes</span> chroniques, entre les règles<br>\n              Causes : <span class=\"nc-blue_bg\">adhérences intra-abdominales des endométrioses évoluées</span> ; <span class=\"nc-blue_bg\">mécanismes neuropathiques</span> (obscurcissent le tableau clinique)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Dysménorrhées : primaire <span>vs</span> secondaire (à distinguer)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>Primaire / essentielle</th><th>Secondaire / organique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Survenue</strong></td>\n            <td><span>6-24 mois</span> après les 1ʳᵉˢ règles (cycles ovulatoires)</td>\n            <td>Tardive ; <em>pendant et en dehors des règles</em> ; <strong>s’aggrave</strong> au fil des cycles</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>Crampes pelviennes/lombaires isolées ± <span><span class=\"nc-brown_bg\">nausées</span></span>, <span><span class=\"nc-brown_bg\">diarrhée</span></span>, <span class=\"nc-brown_bg\">migraines</span>, <span><span class=\"nc-brown_bg\">malaise</span></span><span class=\"nc-brown_bg\"> vagal</span></td>\n            <td>Accompagnée d’autres <span class=\"nc-blue_bg\">symptômes douloureux</span></td>\n          </tr>\n          <tr>\n            <td><strong>Intensité</strong></td>\n            <td>Modérée à <span class=\"nc-red nc-bold\">sévère</span></td>\n            <td><span><span class=\"nc-red nc-bold\">Sévère</span> (EVA &gt; 7/10)</span></td>\n          </tr>\n          <tr>\n            <td><strong>Antalgie</strong></td>\n            <td>Répond aux <span>antalgiques</span> usuels (<span class=\"nc-green_bg\">antispasmodiques</span>, <span><span class=\"nc-green_bg\">paracétamol</span></span>, <span><span class=\"nc-green_bg\">AINS</span></span>)</td>\n            <td>Résistante aux <span>antalgiques</span> usuels</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              Chronologie de la symptomatologie / survenue des règles<br>\n              Rechercher les <strong>dyspareunies profondes balistiques</strong><br>\n              Questionnaires de qualité de vie : <strong><span class=\"nc-blue nc-bold\">EHP-30</span>, <span class=\"nc-blue nc-bold\">EHP-5</span>, <span class=\"nc-blue nc-bold\">SF-36</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen abdominal</strong></td>\n            <td>\n              Souvent pauvre : <span class=\"nc-blue nc-bold\">douleurs non spécifiques</span> (palpation sensible sans défense)<br>\n              En crise douloureuse : peut mimer un abdomen chirurgical\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spéculum</strong></td>\n            <td>\n              Réalisé avec délicatesse (cul-de-sac douloureux au contact)<br>\n              Souvent normal — peut mettre en évidence un <strong><span><span class=\"nc-red nc-bold\">nodule</span></span><span class=\"nc-red nc-bold\"> d’endométriose profonde</span></strong><span class=\"nc-red nc-bold\"> infiltrant le vagin</span> :<br>\n              → <span>rétraction fibreuse</span>, <span>lésion végétante</span>, <span><span class=\"nc-blue_bg\">microkystes noirs</span></span><br>\n              ± taches bleutées du vagin ou du col\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal (<span>TV</span>)</strong></td>\n            <td>\n              <span>À ne pas réaliser si patiente vierge</span><br>\n              <strong><span class=\"nc-red nc-bold\">Cul-de-sac postérieur</span> souple <span class=\"nc-yellow_bg\">mais</span> sensible</strong> → <span class=\"nc-red nc-bold\">endométriose superficielle du cul-de-sac recto-utérin</span><br>\n              <strong><span>Nodule</span> fibreux / <span>lésion</span> végétante palpable</strong> → <span class=\"nc-orange_bg\">endométriose profonde</span> (cul-de-sac vaginal, ligaments utéro-sacrés, Douglas)<br>\n              <strong>Utérus augmenté + sensible</strong> (surtout en période menstruelle) → <span class=\"nc-red nc-bold\">adénomyose</span><br>\n              <strong><span>Masse</span> kystique ovarienne</strong> → <span class=\"nc-red nc-bold\">endométriome</span><br>\n              Utérus rétroversé/peu mobile, ovaires peu mobiles → arguments en faveur\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher rectal (TR)</strong></td>\n            <td>Utile surtout si suspicion de <strong><span><span class=\"nc-orange nc-bold\">nodule</span></span><span class=\"nc-orange nc-bold\"> d’endométriose profonde rétrocervicale</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le diagnostic d’<span class=\"nc-red nc-bold\">endométriose</span> est <em>clinique</em> : la <strong>coelioscopie diagnostique systématique</strong> et la preuve histologique <span>ne sont pas nécessaires</span>. L’écho endovaginale + <span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> pelvienne</span> suffisent pour le bilan d’extension de 1ʳᵉ intention.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 40 — Algies pelviennes</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/endometriosis","label":"Radiopaedia : Endometriosis"}]},{"id":"41-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les conséquences de l’endométriose","contenu":"<div class=\"notion-course\"><p>Les <span>conséquences</span> de l’endométriose se répartissent en <strong>3 axes</strong> : <span class=\"nc-yellow_bg\">manifestations spécifiques d’organe</span> (cataméniales), retentissement sur la fertilité, retentissement sur la qualité de vie. La <span>non-corrélation</span> entre étendue lésionnelle et intensité des symptômes complique le <span>pronostic</span> individuel.</p>\n\n      <h4><span class=\"nc-yellow_bg\">Manifestations spécifiques d’organe</span> (cataméniales)</h4>\n\n      <table>\n        <thead>\n          <tr><th>Atteinte</th><th>Symptômes</th><th>Causes possibles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Digestive</strong></td>\n            <td>\n              <strong><span class=\"nc-yellow_bg\">Dyschésie</span></strong> (difficulté d’exonération) ± <span class=\"nc-yellow_bg nc-bold\">douleurs</span> à la défécation<br>\n              <span class=\"nc-blue_bg\">Diarrhées cataméniales</span> ; <span class=\"nc-blue_bg\">constipations sévères</span> ; ballonnements\n            </td>\n            <td>\n              Localisations digestives — <strong><span class=\"nc-purple nc-bold\">rectum</span> / <span class=\"nc-purple nc-bold\">côlon sigmoïde</span></strong> (2/3 des atteintes digestives) → <em>justifie une <span><span class=\"nc-blue_bg\">IRM</span></span></em><br>\n              Effet irritatif de lésions superficielles ou profondes sur le tube digestif / plexus hypogastriques inférieurs\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Urinaire</strong></td>\n            <td>\n              <strong>SFU cataméniaux</strong> : <span class=\"nc-blue_bg\">cystalgies cataméniales</span>, <span><span class=\"nc-blue_bg\">pollakiurie</span></span><span class=\"nc-blue_bg\"> diurne et nocturne</span>, <span class=\"nc-blue_bg\">urgenturie</span><br>\n              <span class=\"nc-blue_bg\">Impression d’IU</span> avec <span>ECBU stérile</span>\n            </td>\n            <td>\n              <span class=\"nc-orange_bg\">Endométriose profonde de la </span><strong><span class=\"nc-orange_bg\">vessie</span></strong> → <em>justifie une <span><span class=\"nc-blue_bg\">IRM</span></span></em><br>\n              Effet irritatif de lésions superficielles\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Rénale</span></strong></td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">Atrophie rénale à bas bruit</span></strong> (longtemps asymptomatique)<br>\n              Sténose urétérale → dilatation pyélocalicielle en amont (<span>5 %</span> des cas)\n            </td>\n            <td>Nodules profonds engainant / infiltrant les <strong>uretères</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-purple nc-bold\">Diaphragmatique</span> / thoracique</strong></td>\n            <td>\n              <strong>Douleurs scapulaires ou basithoraciques droites</strong><br>\n              <span class=\"nc-blue_bg\">Épisodes de </span><span><span class=\"nc-blue_bg\">pneumothorax cataménial</span></span>\n            </td>\n            <td>Endométriose de l’<strong><span class=\"nc-purple nc-bold\">hémicoupole diaphragmatique droite</span></strong>, <span class=\"nc-purple nc-bold\">pleurale</span>, <span class=\"nc-purple nc-bold\">parenchyme pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sciatique / sacrée</strong></td>\n            <td>Douleurs fessières, <span class=\"nc-blue_bg\">sciatalgies</span> cataméniales</td>\n            <td>Compression des <strong><span class=\"nc-purple nc-bold\">racines sacrées</span></strong> par <span class=\"nc-orange_bg\">endométriose profonde</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mictionnelle (neurogène)</strong></td>\n            <td><strong><span class=\"nc-blue_bg\">Dysuries cataméniales</span></strong></td>\n            <td><span class=\"nc-orange_bg\">Endométriose profonde</span> du vagin sur les <strong><span class=\"nc-purple nc-bold\">nerfs splanchniques moteurs de la vessie</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Infertilité — chiffres et mécanismes</h4>\n\n      <table>\n        <thead>\n          <tr><th>Fréquence</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Endométriose chez les femmes infertiles</td>\n            <td><span>15-20 %</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-yellow_bg nc-bold\">Infertilité</span> chez les femmes endométriosiques</td>\n            <td><span>30-50 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sexuel</strong></td>\n            <td>Dyspareunie + <span><span class=\"nc-blue_bg\">asthénie</span></span><span class=\"nc-blue_bg\"> secondaire aux douleurs chroniques</span> → <span>réduction</span> du nombre de rapports</td>\n          </tr>\n          <tr>\n            <td><strong>Pelvien</strong></td>\n            <td>\n              <strong><span class=\"nc-orange_bg\">Obstruction</span></strong><span class=\"nc-orange_bg\"> intratubaire</span> ou <span class=\"nc-orange_bg\">tubo-ovarienne</span> (empêche la rencontre des gamètes)<br>\n              Inflammation intrapéritonéale / intratubaire (effet néfaste sur l’interaction ovule-spermatozoïde)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utérin</strong></td>\n            <td><span>Adénomyose</span> : défaut d’implantation embryonnaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Ovarien</span></strong></td>\n            <td><span class=\"nc-red_bg\">Destruction du parenchyme ovarien par </span><strong><span class=\"nc-red_bg\">endométriome</span></strong> → altération de la <span>réserve ovarienne</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Évolution</span> des lésions</h4>\n\n      <ul>\n        <li><span class=\"nc-orange_bg\">Adhérences intrapelviennes et intra-abdominales</span></li>\n        <li><span class=\"nc-orange_bg\">Modifications de l’</span><strong><span class=\"nc-orange_bg\">architecture du pelvis</span></strong><span class=\"nc-orange_bg\"> et des organes</span></li>\n        <li>Conséquences potentielles : <span><span class=\"nc-red nc-bold\">phénomènes douloureux</span></span> et/ou <span><span class=\"nc-red nc-bold\">infertilité</span></span></li>\n        <li><span>Évolution</span> <span>imprévisible</span> et variable d’une patiente à l’autre</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span>Drapeaux rouges</span> à connaître.</strong> Toute <em>sciatalgie cataméniale</em>, <em><span>pneumothorax</span> cataménial</em> ou <em>douleur scapulaire cyclique</em> chez une femme jeune doit faire évoquer une <span><span class=\"nc-red\">endométriose</span> extra-pelvienne</span>. Une <strong>atrophie rénale</strong> de découverte fortuite chez une femme symptomatique (dyspareunie, dysménorrhée) impose la recherche d’une <span class=\"nc-red\">endométriose</span> urétérale.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":1},{"id":"41-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et l’objectif de l’imagerie d’une endométriose","contenu":"<div class=\"notion-course\"><ul><li>L’imagerie recherche et cartographie les lésions, notamment endométriomes et <span class=\"nc-orange_bg\">endométriose profonde</span>, pour guider le traitement. Elle s’interprète avec symptômes, examen et projet de grossesse.</li><li>Échographie pelvienne, notamment endovaginale si adaptée et consentie, en première intention. Une échographie experte est utile si suspicion persistante ou bilan complexe.</li><li>IRM pelvienne en complément selon les résultats, pour cartographie, discordance clinico-échographique, localisation difficile ou préparation thérapeutique, conformément aux recommandations 2025.</li><li>Une imagerie normale n’exclut pas une <span class=\"nc-red nc-bold\">endométriose</span> superficielle. Inversement, la sévérité anatomique ne prédit pas directement l’intensité douloureuse.</li><li>La cœlioscopie diagnostique avec histologie n’est plus un passage obligé pour toutes les patientes ; la décision dépend des symptômes, de l’imagerie et de l’objectif thérapeutique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":0},{"id":"41-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la stratégie de prise en charge d’une endométriose","contenu":"<div class=\"notion-course\"><ul><li>Décision partagée selon douleur, retentissement, localisation, atteinte d’organe et projet de grossesse. Ne pas traiter systématiquement une découverte asymptomatique.</li><li>Sans désir immédiat de grossesse : traitement hormonal adapté (contraception combinée ou progestatif selon contre-indications) et antalgiques ; réévaluation de l’efficacité et de la tolérance.</li><li>En cas de désir de grossesse : stratégie de fertilité adaptée, car les traitements suppressifs hormonaux empêchent la conception pendant leur prise et ne constituent pas un traitement de l’infertilité.</li><li>Chirurgie discutée pour douleurs résistantes/intolérance, atteinte d’organe, certaines masses ou situations de fertilité ; décision spécialisée, avec information sur récidive et réserve ovarienne.</li><li>Approche multidisciplinaire si douleur persistante : douleur chronique, plancher pelvien, troubles digestifs/urinaires et soutien psychologique selon besoins. Ne pas réduire une douleur inexpliquée à une cause psychogène.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS–CNGOF · Imagerie de l’endométriose, 2025</a></li></ul></details>","frequence":1}],"astuces":[],"strategie":{"hospit":"<p><strong>Endométriose profonde <span class=\"q\">— recours aux équipes expertes</span></strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> de l'<span class=\"kw-etio\">endométriose profonde</span> nécessite une <strong>réelle expertise</strong> → référer aux <span class=\"kw-def\">équipes chirurgicales multidisciplinaires spécialisées</span></li><li><span class=\"kw-imagerie\">Échographie pelvienne</span> et <span class=\"kw-imagerie\">IRM</span> réalisées préférentiellement par des <strong>radiologues référents</strong> en endométriose</li></ul><p><strong>Infertilité <span class=\"q\">— orientation vers l'AMP</span></strong></p><ul><li>Discussion au cas par cas entre <span class=\"kw-ttt\">FIV</span> (possible même en présence d'<span class=\"kw-etio\">endométriomes</span>) et <strong><span class=\"kw-ttt\">chirurgie</span></strong></li><li>En cas d'<span class=\"kw-etio\">endométriome ovarien</span> ou d'altération de la <span class=\"kw-alerte\">réserve ovarienne</span> → envisager une <span class=\"kw-ttt\">préservation de la fertilité</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Sténose urétérale</span> avec <span class=\"kw-alerte\">hydronéphrose</span> ou <span class=\"kw-alerte\">atrophie rénale silencieuse</span> — longtemps asymptomatique (<span class=\"kw-chiffre\">5 %</span> des endométrioses profondes)</li><li><span class=\"kw-alerte\">Pneumothorax cataménial</span> récidivant — évoquer une <span class=\"kw-etio\">endométriose diaphragmatique</span>, <span class=\"kw-etio\">pleurale</span> ou <span class=\"kw-etio\">pulmonaire</span></li><li><span class=\"kw-alerte\">Insuffisance ovarienne prématurée</span> après chirurgies itératives des <span class=\"kw-etio\">endométriomes</span> récidivés — conséquence de la destruction du parenchyme ovarien sans plan de clivage</li><li><span class=\"kw-alerte\">Sciatalgies cataméniales</span> ou douleurs fessières cycliques — compression des <span class=\"kw-etio\">racines sacrées</span> par endométriose profonde</li><li>Toute <span class=\"kw-alerte\">douleur cyclique extra-pelvienne</span> (scapulaire droite, basithoracique) chez la femme jeune — évoquer une <span class=\"kw-etio\">endométriose extra-pelvienne</span></li></ul>","principes":"<p>PEC <strong>symptomatique</strong> : on traite les <em>conséquences</em> (douleur, infertilité), pas la maladie elle-même. <span class=\"kw-ttt\">Traitement médical hormonal</span> = <strong>1ʳᵉ intention</strong> empirique, <strong>suspensif</strong> (sans effet curatif). <span class=\"kw-ttt\">Chirurgie</span> = <strong>2ᵉ intention</strong>, réservée aux échecs/intolérances.</p><p><strong>Traitement non hormonal</strong></p><ul><li><span class=\"kw-ttt\">Paracétamol</span> · <span class=\"kw-ttt\">antispasmodiques</span> · <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ci\">AINS à éviter au long cours</span>)</li><li>Recours au <strong>centre anti-douleur</strong> si <span class=\"kw-clinique\">douleur chronique</span> résistante aux <span class=\"kw-ttt\">antalgiques</span> usuels</li></ul><p><strong>Thérapies hormonales <span class=\"q\">— traitement suspensif en continu</span></strong></p><p>Arrêt avant ménopause → risque de <span class=\"kw-alerte\">reprise évolutive</span> et de perte de l'effet <span class=\"kw-ttt\">antalgique</span></p><ul><li><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">DIU au lévonorgestrel</span></li><li><strong>2ᵉ intention</strong> : <span class=\"kw-ttt\">contraceptions microprogestatives</span> ; <span class=\"kw-ttt\">COP en continu</span> (pour éviter les hémorragies de privation)</li><li>Durée : long, poursuivi jusqu'au <strong>désir de <span class=\"kw-ci\">grossesse</span></strong> ou jusqu'à la <span class=\"kw-clinique\">ménopause</span></li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> cœlioscopique <span class=\"q\">— 2ᵉ intention</span></strong></p><p>Post-<span class=\"kw-ttt\">chirurgie</span> : <span class=\"kw-ttt\">aménorrhée hormonale</span> pour réduire le risque de <span class=\"kw-alerte\">récidive lésionnelle</span></p><ul><li><strong>Indications</strong> : absence d'efficacité ou <span class=\"kw-ci\">intolérance aux traitements médicaux</span> bien conduits</li><li><strong>Voie</strong> : <span class=\"kw-ttt\">cœlioscopique</span> (préférée à la laparotomie)</li><li><span class=\"kw-alerte\">Une seule intervention bien menée</span> — éviter les chirurgies itératives incomplètes</li><li>Endométriose profonde : <span class=\"kw-ttt\">résection nodulaire</span> par équipe multidisciplinaire experte</li></ul><p><strong>Infertilité — AMP</strong></p><ul><li><strong>1ᵉʳ temps</strong> : interruption du traitement hormonal + <strong>bilan complet</strong> (<span class=\"kw-bio\">dysovulation</span>, <span class=\"kw-bio\">altérations spermatiques</span>…)</li><li><strong>2ᵈ temps</strong> : <span class=\"kw-ttt\">AMP</span> guidée au cas par cas (<span class=\"kw-def\">stade</span>, âge, délai d'infertilité, examens)</li><li><span class=\"kw-ttt\">FIV</span> possible même en présence d'<span class=\"kw-etio\">endométriomes</span> — la <span class=\"kw-ttt\">chirurgie</span> n'est <span class=\"kw-ci\">pas systématique</span> (risque de <span class=\"kw-alerte\">chute de la réserve ovarienne</span>)</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/endometriosis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/adenomyosis","label":"radiopaedia.org"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Endometriose202025_imagerie_recommandations_ca.pdf","label":"HAS–CNGOF · Imagerie de l’endométriose, 2025"}],"cards":[{"i":"1b6c59f861db","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelles sont les différentes catégories anatomiques des lésions d'endométriose ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-red nc-bold\">endométriose</span> péritonéale superficielle</strong> : lésions de petite taille limitées au péritoine.</li><li>L'<strong><span class=\"nc-red nc-bold\">endométriome</span></strong> : lésion kystique ovarienne (kyste endométriosique).</li><li>L'<strong><span class=\"nc-red nc-bold\">endométriose</span> pelvienne <span class=\"nc-red nc-bold\">profonde</span></strong> : nodules infiltrant à &gt; <strong>5 mm</strong> sous le péritoine.</li><li>Les localisations à <strong>distance</strong> : rares mais possibles (ex: <span class=\"nc-purple nc-bold\">pulmonaire</span>, <span class=\"nc-purple nc-bold\">cérébrale</span>).</li></ul></div>"},{"i":"4948cd5bd45b","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Comment distingue-t-on une dysménorrhée primaire d'une dysménorrhée secondaire ?","a":"<div class=\"notion-course\"><ul><li>La <strong>dysménorrhée primaire</strong> (ou essentielle) apparaît <strong>6 à 24 mois après les premières règles</strong>, est idiopathique et sensible aux antalgiques usuels.</li><li>La <strong>dysménorrhée secondaire</strong> apparaît plus tardivement, s'aggrave au fil des cycles, est souvent estimée à un score EVA &gt; 7/10 et est résistante aux antalgiques.</li></ul></div>"},{"i":"86f0f83b32ec","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Dans quel contexte l'endométriose devient-elle une maladie ?","a":"<div class=\"notion-course\"><p>L'endométriose devient une maladie lorsqu'elle se traduit par des symptômes tels que des <strong><span class=\"nc-red nc-bold\">douleurs</span></strong> et/ou une <strong><span class=\"nc-red nc-bold\">infertilité</span></strong>.</p></div>"},{"i":"9c65f2603798","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition de l'adénomyose ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-yellow_bg\">adénomyose</span> est caractérisée par une <strong><span class=\"nc-yellow_bg\">infiltration diffuse ou focale du myomètre</span></strong><span class=\"nc-yellow_bg\"> par des cellules endométriales</span>, conduisant à la formation de <strong>microkystes endométriaux intra-myométriaux</strong>.</p></div>"},{"i":"a4ba79a2ef61","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition histologique de l'endométriose ?","a":"<div class=\"notion-course\"><p>L'endométriose est définie histologiquement par la <span class=\"nc-yellow_bg\">présence de </span><strong><span class=\"nc-yellow_bg\">tissu de type endométrial en dehors de la cavité utérine</span></strong>.</p></div>"},{"i":"d06e2d46f409","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition d'une dysménorrhée ?","a":"<div class=\"notion-course\"><p>Une dysménorrhée correspond à des <strong>règles douloureuses</strong>, c'est-à-dire des <span class=\"nc-yellow_bg nc-bold\">douleurs</span> <span class=\"nc-yellow_bg nc-bold\">pelviennes</span> contemporaines des menstruations.</p></div>"},{"i":"2ea418a38365","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quelle est la prévalence globale de l'endométriose chez les femmes en âge de procréer ?","a":"<div class=\"notion-course\"><p>La prévalence globale de l'endométriose est estimée entre <strong>6 et 15 %</strong> des femmes en âge de procréer, toutes formes confondues.</p></div>"},{"i":"504bd05970fe","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quel est le délai moyen avant le diagnostic d'endométriose ?","a":"<div class=\"notion-course\"><p>Le délai diagnostique de l'endométriose est de <strong>7 à 10 ans</strong> selon les études.</p></div>"},{"i":"903b76b975eb","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quels sont les principaux facteurs de risque de l'endométriose liés au reflux tubaire menstruel ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-blue_bg\">Ménarche précoce</span></strong></li><li><strong><span class=\"nc-blue_bg\">Nulliparité</span></strong></li><li><strong><span class=\"nc-blue_bg\">Cycles courts</span></strong>, <strong><span class=\"nc-blue_bg\">hyperménorrhée</span></strong>, <strong><span class=\"nc-blue_bg\">ménorragie</span></strong></li><li><strong>Anomalie müllérienne</strong> (malformation utérine)</li><li><strong><span class=\"nc-pink_bg\">Geste endo-utérin</span></strong></li></ul></div>"},{"i":"cf4aebdc3124","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quelle est la prévalence de l'adénomyose et son association avec l'endométriose ?","a":"<div class=\"notion-course\"><p>L'adénomyose pourrait concerner près de <strong>50 %</strong> des femmes, avec une incidence augmentant après <strong>35 ans</strong>. Elle est souvent <strong>associée</strong> à l'<span class=\"nc-red nc-bold\">endométriose</span>.</p></div>"},{"i":"242be3302c54","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelle est la triade symptomatique classique de l'endométriose chez une femme avec règles mensuelles et activité ovarienne non freinée ?","a":"<div class=\"notion-course\"><p>La triade symptomatique typique de l'endométriose comprend :</p><ul><li>Des <strong><span class=\"nc-yellow_bg\">symptômes douloureux de survenue cyclique</span></strong><span class=\"nc-yellow_bg\"> rythmée par les règles</span>.</li><li>Des <strong><span class=\"nc-yellow_bg\">manifestations spécifiques d'organe</span></strong> (digestives, urinaires, scapulaires, etc.).</li><li>L'<strong>infertilité</strong>.</li></ul></div>"},{"i":"5e4432e86b1a","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quels sont les signes à rechercher lors de l'examen clinique (spéculum, toucher vaginal, toucher rectal) suggérant une endométriose ?","a":"<div class=\"notion-course\"><p>Les signes cliniques orientant vers une endométriose sont :</p><ul><li><strong>Au spéculum</strong> : souvent normal, <span class=\"nc-yellow_bg\">mais</span> peut révéler un <strong><span class=\"nc-red nc-bold\">nodule d'endométriose profonde infiltrant le vagin</span></strong> (rétraction fibreuse, lésion végétante, <span class=\"nc-blue_bg\">microkystes noirs</span> ± taches bleutées du vagin ou du col).</li><li><strong>Au toucher vaginal</strong> :</li><ul><li><strong><span class=\"nc-red nc-bold\">Cul-de-sac postérieur</span> souple <span class=\"nc-yellow_bg\">mais</span> sensible</strong> : suggère une <span class=\"nc-red nc-bold\">endométriose superficielle du cul-de-sac recto-utérin</span>.</li><li><strong>Nodule fibreux / lésion végétante palpable</strong> : évoque une <span class=\"nc-orange_bg\">endométriose profonde</span> (cul-de-sac vaginal, ligaments utéro-sacrés, Douglas).</li><li><strong>Utérus augmenté de taille + sensible</strong> (surtout en période menstruelle) : oriente vers une <strong><span class=\"nc-red nc-bold\">adénomyose</span></strong>.</li><li><strong>Masse kystique ovarienne</strong> : signe un <strong><span class=\"nc-red nc-bold\">endométriome</span></strong>.</li><li>Utérus rétroversé/peu mobile, ovaires peu mobiles sont des arguments en faveur.</li></ul><li><strong>Au toucher rectal</strong> : utile si suspicion de <strong><span class=\"nc-orange nc-bold\">nodule d'endométriose profonde rétrocervicale</span></strong>.</li></ul></div>"},{"i":"8fb5670d5136","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelles sont les caractéristiques cliniques de la dysménorrhée d'origine endométriosique ?","a":"<div class=\"notion-course\"><p>La dysménorrhée endométriosique présente les caractéristiques suivantes :</p><ul><li>C'est le <strong>premier symptôme dans la majorité des cas</strong>.</li><li>Type de douleur : <strong>sourde</strong>.</li><li>Topographie : <strong>abdomino-pelvienne</strong> (<span class=\"nc-red nc-bold\">hypogastre</span>, <span class=\"nc-red nc-bold\">fosses iliaques</span>, <span class=\"nc-red nc-bold\">flancs</span>, <span class=\"nc-red nc-bold\">bas du dos</span>).</li><li>Délai : souvent dès les <strong>premières règles</strong>.</li><li>Horaire : <strong>cyclique</strong>, survenant juste <strong>avant les règles</strong>.</li><li>Durée : généralement <strong><span class=\"nc-pink nc-bold\">1-2 jours</span></strong>, parfois plus (souvent en crescendo).</li><li>Souvent associée à des <strong><span class=\"nc-blue_bg\">ménorragies</span></strong>.</li><li>Calmants : <strong>AINS</strong> et pilule en mode cyclique sont souvent efficaces initialement.</li><li>Conséquence : <strong><span class=\"nc-red nc-bold\">absentéisme</span> scolaire ou professionnel</strong> fréquent.</li></ul></div>"},{"i":"d443dcf6ddd0","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Comment distinguer une dysménorrhée primaire d'une dysménorrhée secondaire, évocatrice d'endométriose ?","a":"<div class=\"notion-course\"><p>Les éléments clés pour distinguer une dysménorrhée primaire d'une dysménorrhée secondaire, potentiellement liée à l'endométriose, sont :</p><ul><li><strong>Survenue</strong> : la primaire apparaît 6-24 mois après les 1ères règles (cycles ovulatoires) ; la secondaire est <strong>tardive</strong>, survient pendant et en dehors des règles, et <strong>s'aggrave au fil des cycles</strong>.</li><li><strong>Clinique</strong> : la primaire se manifeste par des crampes pelviennes/lombaires isolées ; la secondaire est <strong>accompagnée d'autres <span class=\"nc-blue_bg\">symptômes douloureux</span></strong>.</li><li><strong>Intensité</strong> : la primaire est modérée à <span class=\"nc-red nc-bold\">sévère</span> ; la secondaire est <strong><span class=\"nc-red nc-bold\">sévère</span> (EVA &gt; 7/10)</strong>.</li><li><strong>Antalgie</strong> : la primaire répond aux antalgiques usuels (<span class=\"nc-green_bg\">antispasmodiques</span>, <span class=\"nc-green_bg\">paracétamol</span>, <span class=\"nc-green_bg\">AINS</span>) ; la secondaire est <strong>résistante aux antalgiques usuels</strong>.</li></ul></div>"},{"i":"db0ad86aad26","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelle est l'importance du diagnostic clinique dans l'endométriose et quelle est la place de la cœlioscopie et de l'histologie ?","a":"<div class=\"notion-course\"><p>Le diagnostic d'<span class=\"nc-red nc-bold\">endométriose</span> est <strong>avant tout clinique</strong>. La cœlioscopie diagnostique systématique et la preuve histologique <strong>ne sont pas nécessaires pour le diagnostic positif</strong>. L'échographie endovaginale et l'<span class=\"nc-blue_bg\">IRM pelvienne</span> sont suffisantes pour le bilan d'extension de première intention.</p></div>"},{"i":"288978c4d3f3","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quelles sont les manifestations urinaires de l'endométriose et quel est le risque rénal associé ?","a":"<div class=\"notion-course\"><p>Les manifestations urinaires comprennent des <strong>syndromes fonctionnels urinaires (SFU) cataméniaux</strong> tels que :</p><ul><li><strong><span class=\"nc-blue_bg\">Cystalgies cataméniales</span></strong>.</li><li><span class=\"nc-blue_bg\">Pollakiurie diurne et nocturne</span>.</li><li>Urgenturie.</li><li>Une impression d'infection urinaire avec <strong>ECBU stérile</strong>.</li></ul><p>Le risque rénal majeur est l'<strong><span class=\"nc-red nc-bold\">atrophie rénale à bas bruit</span></strong> due à une <strong>sténose urétérale</strong>, pouvant entraîner une <strong>dilatation pyélocalicielle en amont</strong> dans environ <strong>5 %</strong> des cas.</p></div>"},{"i":"289ab9af0398","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Comment l'endométriose affecte-t-elle la fertilité ?","a":"<div class=\"notion-course\"><p>L'endométriose affecte la fertilité par plusieurs mécanismes :</p><ul><li>L'<strong><span class=\"nc-orange_bg\">obstruction intratubaire</span></strong> ou <span class=\"nc-orange_bg\">tubo-ovarienne</span> qui empêche la rencontre des gamètes.</li><li>L'<strong>inflammation intrapéritonéale</strong> ou intratubaire ayant un effet néfaste sur l'interaction ovule-spermatozoïde.</li><li>L'<strong><span class=\"nc-red_bg\">adénomyose</span></strong> (<span class=\"nc-red nc-bold\">endométriose</span> utérine) peut causer un défaut d'implantation embryonnaire.</li><li>Les <strong><span class=\"nc-yellow_bg\">endométriomes ovariens</span></strong> peuvent détruire le parenchyme ovarien et altérer la réserve ovarienne.</li><li>Les <strong><span class=\"nc-orange_bg\">adhérences intrapelviennes</span></strong><span class=\"nc-orange_bg\"> et intra-abdominales</span> modifient l'architecture du pelvis.</li></ul></div>"},{"i":"565b6225f5f2","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quels sont les trois axes principaux des conséquences de l'endométriose ?","a":"<div class=\"notion-course\"><p>Les trois axes principaux des conséquences de l'endométriose sont :</p><ul><li>Les <strong><span class=\"nc-yellow_bg\">manifestations spécifiques d'organe</span></strong> (cataméniales).</li><li>Le <strong>retentissement sur la fertilité</strong>.</li><li>Le <strong>retentissement sur la qualité de vie</strong>.</li></ul></div>"},{"i":"99b56947bac0","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quelles sont les principales manifestations digestives de l'endométriose ?","a":"<div class=\"notion-course\"><p>Les principales manifestations digestives de l'endométriose comprennent :</p><ul><li>La <strong><span class=\"nc-yellow_bg\">dyschésie</span></strong> (difficulté d'exonération) ± douleurs à la défécation.</li><li>Les <strong><span class=\"nc-blue_bg\">diarrhées cataméniales</span></strong>.</li><li>Les <span class=\"nc-blue_bg\">constipations sévères</span>.</li><li>Les ballonnements.Ces symptômes sont souvent observés en cas d'atteinte du <strong><span class=\"nc-purple nc-bold\">rectum</span></strong> ou du <strong><span class=\"nc-purple nc-bold\">côlon sigmoïde</span></strong>.</li></ul></div>"},{"i":"c9fe28105841","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quels sont les signes d'alerte (drapeaux rouges) qui doivent faire évoquer une endométriose extra-pelvienne ?","a":"<div class=\"notion-course\"><p>Les signes d'alerte pour une endométriose extra-pelvienne sont :</p><ul><li>Toute <strong>sciatalgie cataméniale</strong>.</li><li>Un <strong>pneumothorax cataménial</strong>.</li><li>Une <strong>douleur scapulaire cyclique</strong> chez une femme jeune.</li><li>Une <strong>atrophie rénale</strong> de découverte fortuite chez une femme présentant des symptômes comme une dyspareunie ou une dysménorrhée peut également orienter vers une <span class=\"nc-red nc-bold\">endométriose</span> urétérale.</li></ul></div>"},{"i":"e24b0d201e01","n":41,"o":"41-3","u":"Physiopathologie","t":"Connaître la physiopathologie de l’endométriose","q":"Que retenir concernant la physiopathologie de l’endométriose ?","a":"<div class=\"notion-course\"><p>La <span>physiopathologie</span> de l’endométriose reste partiellement élucidée. La théorie dominante associe un <strong><span><span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire de sang menstruel</span></strong> à une <strong>capacité d’élimination péritonéale diminuée</strong> et à des anomalies hormonales/inflammatoires locales favorisant l’implantation et la <span class=\"nc-red nc-bold\">persistance</span> des lésions.</p>\n\n      <h4>Caractéristique histologique principale</h4>\n\n      <ul>\n        <li>Composante de <span>tissu endométrial</span> entouré d’un <strong><span>stroma</span></strong></li>\n        <li>Comportement cyclique mimant celui de l’endomètre :\n          <ol>\n            <li><span class=\"nc-blue_bg\">Croissance cyclique</span> → <span class=\"nc-blue_bg\">desquamation</span> → hémorragie pendant les règles</li>\n            <li>Sang et cellules desquamées <strong>non éliminés</strong> → <span><span class=\"nc-red nc-bold\">réaction inflammatoire cyclique locale</span></span></li>\n          </ol>\n        </li>\n      </ul>\n\n      <h4>Provenance des lésions — arguments pour le <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire</h4>\n\n      <ul>\n        <li>FR de <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire ↗ le risque d’endométriose</li>\n        <li><span class=\"nc-blue_bg\">Prédominance des lésions dans le </span><strong><span class=\"nc-blue_bg\">compartiment postérieur du pelvis et à gauche</span></strong></li>\n        <li>Implants disséminés sur le trajet de circulation du liquide péritonéal (analogie avec les métastases du cancer de l’ovaire)</li>\n        <li><strong>Péritoine des femmes atteintes</strong> aurait une capacité diminuée d’élimination du sang et des cellules (le <span class=\"nc-yellow_bg nc-bold\">reflux</span> tubaire survient chez la majorité des femmes, mais toutes ne développent pas une endométriose)</li>\n      </ul>\n\n      <h4>Mécanismes de <span class=\"nc-red nc-bold\">croissance</span> et de <span class=\"nc-red nc-bold\">persistance</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies hormonales</strong></td>\n            <td>\n              <strong><span>Surexpression du récepteur aux œstrogènes</span></strong><br>\n              <strong><span>Résistance à la progestérone</span></strong><br>\n              <strong><span>Surexpression de l’aromatase</span></strong><br>\n              → favorise <span class=\"nc-red nc-bold\">croissance</span> + <span class=\"nc-red nc-bold\">persistance</span> des lésions\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réaction <span>inflammatoire</span></strong></td>\n            <td>\n              Production locale d’<span>IL-6</span>, de <span>TNF</span>, stress oxydatif<br>\n              → endométriose = <em>maladie <span>inflammatoire</span> locale</em> avec réponse immunitaire péritonéale\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Invasion / néoangiogenèse</strong></td>\n            <td>\n              <span class=\"nc-pink_bg\">Surexpression des </span><strong><span><span class=\"nc-pink_bg\">métalloprotéinases</span></span></strong><br>\n              <span class=\"nc-pink_bg\">Surexpression du </span><span><span class=\"nc-pink_bg\">VEGF</span></span><br>\n              → potentiel d’invasion et de néoangiogenèse marqué\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes des douleurs</h4>\n\n      <ul>\n        <li><span class=\"nc-brown_bg\">Nociception</span> · <span class=\"nc-brown_bg\">hyperalgie</span> · <strong><span><span class=\"nc-brown_bg\">sensibilisation centrale</span></span></strong></li>\n        <li><strong>Corrélation</strong> entre <em>typologie</em> des douleurs et <em>localisation</em> des lésions</li>\n        <li><span>Pas de lien</span> entre <em>intensité des symptômes</em> et <em>étendue/profondeur</em> de l’endométriose</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <span class=\"nc-red nc-bold\">endométriose</span> <em>peu étendue</em> peut être <strong>très symptomatique</strong>, et inversement une atteinte <span class=\"nc-red nc-bold\">profonde</span> peut être <em>pauci-symptomatique</em>. Le bilan d’extension n’est <strong>jamais</strong> proportionné à la sévérité clinique.\n      </div></div>"},{"i":"ba1258f37b55","n":41,"o":"41-6","u":"Examens complémentaires","t":"Connaître les indications et l’objectif de l’imagerie d’une endométriose","q":"Que retenir concernant les indications et l’objectif de l’imagerie d’une endométriose ?","a":"<div class=\"notion-course\"><ul><li>L’imagerie recherche et cartographie les lésions, notamment endométriomes et <span class=\"nc-orange_bg\">endométriose profonde</span>, pour guider le traitement. Elle s’interprète avec symptômes, examen et projet de grossesse.</li><li>Échographie pelvienne, notamment endovaginale si adaptée et consentie, en première intention. Une échographie experte est utile si suspicion persistante ou bilan complexe.</li><li>IRM pelvienne en complément selon les résultats, pour cartographie, discordance clinico-échographique, localisation difficile ou préparation thérapeutique, conformément aux recommandations 2025.</li><li>Une imagerie normale n’exclut pas une <span class=\"nc-red nc-bold\">endométriose</span> superficielle. Inversement, la sévérité anatomique ne prédit pas directement l’intensité douloureuse.</li><li>La cœlioscopie diagnostique avec histologie n’est plus un passage obligé pour toutes les patientes ; la décision dépend des symptômes, de l’imagerie et de l’objectif thérapeutique.</li></ul></div>"},{"i":"71d9c7fc5a32","n":41,"o":"41-7","u":"Prise en charge","t":"Connaître les principes de la stratégie de prise en charge d’une endométriose","q":"Que retenir concernant les principes de la stratégie de prise en charge d’une endométriose ?","a":"<div class=\"notion-course\"><ul><li>Décision partagée selon douleur, retentissement, localisation, atteinte d’organe et projet de grossesse. Ne pas traiter systématiquement une découverte asymptomatique.</li><li>Sans désir immédiat de grossesse : traitement hormonal adapté (contraception combinée ou progestatif selon contre-indications) et antalgiques ; réévaluation de l’efficacité et de la tolérance.</li><li>En cas de désir de grossesse : stratégie de fertilité adaptée, car les traitements suppressifs hormonaux empêchent la conception pendant leur prise et ne constituent pas un traitement de l’infertilité.</li><li>Chirurgie discutée pour douleurs résistantes/intolérance, atteinte d’organe, certaines masses ou situations de fertilité ; décision spécialisée, avec information sur récidive et réserve ovarienne.</li><li>Approche multidisciplinaire si douleur persistante : douleur chronique, plancher pelvien, troubles digestifs/urinaires et soutien psychologique selon besoins. Ne pas réduire une douleur inexpliquée à une cause psychogène.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418191aabac9c00dde5baf?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Symptômes évocateurs ?","detail":"<ul><li>Dysménorrhée, dyspareunie profonde, douleurs cycliques digestives/urinaires, infertilité.</li></ul>","branches":[{"label":"Oui","to":"bilan"},{"label":"Autre tableau","to":"differentiel"}]},{"id":"bilan","kind":"decision","label":"Examen et échographie adaptée","detail":"<ul><li>Consensuel ; échographie experte et/ou IRM selon suspicion et résultat initial.</li></ul>","branches":[{"label":"Atteinte d’organe/complexité","to":"expert"},{"label":"Douleur sans complication","to":"projet"}]},{"id":"expert","kind":"finish","label":"Filière spécialisée","detail":"<ul><li>Cartographier, discuter chirurgie et préservation ; ne pas opérer sur l’image seule.</li></ul>","branches":[]},{"id":"projet","kind":"decision","label":"Projet de grossesse immédiat ?","detail":"<ul><li>Retentissement, préférences et risques.</li></ul>","branches":[{"label":"Oui","to":"fertilite"},{"label":"Non","to":"symptomes"}]},{"id":"fertilite","kind":"finish","label":"Prise en charge de fertilité adaptée","detail":"<ul><li>Les traitements hormonaux bloquants ne favorisent pas une conception pendant leur prise.</li></ul>","branches":[]},{"id":"symptomes","kind":"finish","label":"Antalgie et traitement hormonal si approprié","detail":"<ul><li>Réévaluer efficacité/tolérance ; chirurgie si indication partagée.</li></ul>","branches":[]},{"id":"differentiel","kind":"uncertain","label":"Rechercher les autres causes de douleur","detail":"<ul><li>Une imagerie normale n’exclut pas toute endométriose.</li></ul>","branches":[]}]}};
